"""Final local editorial revisions after complete reading; no database access."""
import json
from pathlib import Path

root = Path(__file__).parent
def read(name):
    return json.loads((root / name).read_text(encoding='utf-8'))
def save(name, value):
    (root / name).write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
drafts = read('440-biography-drafts-2026-11-04.json')
patches = read('440-biography-patches-2026-11-04.json')
def replace(slug, locale, old, new):
    assert old in drafts[slug][locale], (slug, locale, old)
    drafts[slug][locale] = drafts[slug][locale].replace(old, new)
def patch(slug, locale, index, text):
    old = next((p for p in patches if p['slug']==slug and p['locale']==locale and p.get('index')==index), None)
    if old: old['text']=text
    else: patches.append(dict(slug=slug, locale=locale, index=index, text=text))

